# Writes stars.txt: a disc of small glowing cubes 8 m below the asteroid's top, 12 m across in
# radius, so that from the high orthographic camera they fill the dark around the rock at any yaw.
# Two sizes: most 0.07 m (one art pixel), a few 0.12 m. Run: python3 make_stars.py
import math, random
rnd = random.Random(21)
lines = ["# Star field: generated by make_stars.py (static, unlit). Up Z.", "new"]
names = []
for i in range(150):
    r = 4.0 + math.sqrt(rnd.random()) * 9.0
    a = rnd.uniform(0, 2 * math.pi)
    z = rnd.uniform(-10.0, -6.0)
    size = 0.12 if rnd.random() < 0.15 else 0.07
    n = f"S{i}"
    names.append(n)
    lines.append(f"add mesh cube --name {n} --size {size} --location {r*math.cos(a):.3f} {r*math.sin(a):.3f} {z:.3f}")
lines.append("material new Star --base-color 0.933 1.0 0.8 --emission 0.933 1.0 0.8")
lines.append("select " + " ".join(names))
lines.append("active S0")
lines.append("join")
lines.append("rename S0 Stars")
lines.append("material assign Star")
lines.append("export stars.glb")
open("stars.txt", "w").write("\n".join(lines) + "\n")
